// Package dryrun tests — T-12 characterization (Phase 1).
//
// THE LAW (roadmap Phase 1 + task list standing orders): the Python
// characterization tests are ported FIRST, then the code; the goldens were
// GENERATED by running the unmodified Python reference app
// (assadigit/GitCurator @ 98f4fc7) via testdiff/goldens/dump_storage.py —
// never hand-typed. Regenerate with:
//
//	python3 testdiff/goldens/dump_storage.py
//
// Ported suites: app/tests/test_phase0.py TestDryRunModule (tests 1–3, 5–7
// here; its test 4 — storage atomic writes gated — lives in
// internal/storage/storage_test.go because the gate belongs to the atomic
// writers). The sqlite-level assertions of Python test 5 ("the shadow sees
// real rows / writes land in the shadow") are deliberately deferred to
// Phase 2 (T-20/T-24 open real cache.db fixtures through modernc); T-12
// pins the file/concurrency contract dryrun.py itself owns: byte-identical
// copy incl. WAL sidecars, mtime preservation, missing-source info path,
// no deadlock. Deferred assertions stay on the books — recorded in
// SESSION-004.md, not silently dropped.
package dryrun

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"testing"
	"time"
)

// setUp/tearDown mirror TestDryRunModule: every test starts and ends with
// the switch OFF and the log empty.
func setUp(t *testing.T) {
	t.Helper()
	Disable()
	Clear()
}

func tearDown(t *testing.T) {
	t.Helper()
	Disable()
	Clear()
}

