// Port of test_default_off_and_helpers_perform_real_operations.
func TestDefaultOffAndHelpersPerformRealOperations(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	tmp := t.TempDir()
	if IsEnabled() {
		t.Fatal("dry-run must be OFF by default")
	}
	if err := MkdirAll(filepath.Join(tmp, "a"), true); err != nil {
		t.Fatalf("makedirs: %v", err)
	}
	if err := WriteText(filepath.Join(tmp, "a", "f.txt"), "hello"); err != nil {
		t.Fatalf("write_text: %v", err)
	}
	if err := AppendText(filepath.Join(tmp, "a", "f.txt"), "!"); err != nil {
		t.Fatalf("append_text: %v", err)
	}
	if err := WriteText(filepath.Join(tmp, "mv.txt"), "x"); err != nil {
		t.Fatalf("write_text: %v", err)
	}
	if err := Move(filepath.Join(tmp, "mv.txt"), filepath.Join(tmp, "moved.txt")); err != nil {
		t.Fatalf("move: %v", err)
	}
	if got := EntryCount(); got != 0 {
		t.Fatalf("nothing recorded while OFF; got %d entries", got)
	}
	got, err := os.ReadFile(filepath.Join(tmp, "a", "f.txt"))
	if err != nil || string(got) != "hello!" {
		t.Fatalf("f.txt = %q, %v; want %q", got, err, "hello!")
	}
	if _, err := os.Stat(filepath.Join(tmp, "moved.txt")); err != nil {
		t.Fatalf("moved.txt missing after move: %v", err)
	}
	if err := Remove(filepath.Join(tmp, "moved.txt")); err != nil {
		t.Fatalf("remove: %v", err)
	}
	if _, err := os.Stat(filepath.Join(tmp, "moved.txt")); !os.IsNotExist(err) {
		t.Fatalf("moved.txt still exists after remove: %v", err)
	}
}

// Port of test_enabled_helpers_log_instead_of_touching_disk.
func TestEnabledHelpersLogInsteadOfTouchingDisk(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	tmp := t.TempDir()
	Enable()
	target := filepath.Join(tmp, "note.md")
	_ = MkdirAll(filepath.Join(tmp, "folder"), true)
	_ = WriteText(target, "---\nsource: x\n---\n")
	_ = AppendText(target, "more")
	_ = WriteText(filepath.Join(tmp, "mv.txt"), "x")
	_ = Move(filepath.Join(tmp, "mv.txt"), filepath.Join(tmp, "elsewhere.txt"))
	_ = Remove(target)

	// disk untouched
	names, _ := os.ReadDir(tmp)
	if len(names) != 0 {
		t.Fatalf("disk was touched while enabled: %v", names)
	}
	// log complete, with previews
	ops := map[string]bool{}
	for _, e := range Entries() {
		ops[e.Op] = true
	}
	for _, want := range []string{"makedirs", "write", "append", "move", "remove"} {
		if !ops[want] {
			t.Errorf("op %q missing from the log; ops = %v", want, ops)
		}
	}
	sawPreview := false
	for _, e := range Entries() {
		if e.Op == "write" && strings.Contains(e.Preview, "source: x") {
			sawPreview = true
		}
	}
	if !sawPreview {
		t.Error("write previews missing content")
	}
}

// Port of test_enable_clears_previous_log_disable_keeps_entries.
func TestEnableClearsPreviousLogDisableKeepsEntries(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	Enable()
	Record("write", "/tmp/x.md", "abc", "")
	if got := EntryCount(); got != 1 {
		t.Fatalf("entry_count = %d; want 1", got)
	}
	Disable()
	if got := EntryCount(); got != 1 {
		t.Fatalf("disable must KEEP the log for the report; got %d", got)
	}
	if IsEnabled() {
		t.Fatal("is_enabled after disable")
	}
	Enable()
	if got := EntryCount(); got != 0 {
		t.Fatalf("enable must start a fresh log; got %d", got)
	}
}

// Port of test_shadow_cache_reads_real_state_writes_are_discarded —
// file/concurrency level (see the package comment for the sqlite-level
// deferral to Phase 2).
func TestShadowCacheReadsRealStateWritesAreDiscarded(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	tmp := t.TempDir()
	real := filepath.Join(tmp, "cache.db")
	realBody := []byte("REAL-CACHE-" + strings.Repeat("0123456789abcdef", 64))
	walBody := []byte("WAL-" + strings.Repeat("\x00\x01\x02", 33))
	shmBody := []byte("SHM-" + strings.Repeat("\xff", 100))
	for p, b := range map[string][]byte{
		real:          realBody,
		real + "-wal": walBody,
		real + "-shm": shmBody,
	} {
		if err := os.WriteFile(p, b, 0o666); err != nil {
			t.Fatal(err)
		}
	}

	Enable()
	shadow := ShadowCachePath(real)
	if shadow == real {
		t.Fatalf("shadow must not be the real cache: %s", shadow)
	}
	// the shadow sees the real bytes (copy2 parity: content + mtime)…
	if got, _ := os.ReadFile(shadow); !bytesEqual(got, realBody) {
		t.Fatalf("shadow content diverged (%d bytes)", len(got))
	}
	if got, _ := os.ReadFile(shadow + "-wal"); !bytesEqual(got, walBody) {
		t.Fatal("shadow -wal sidecar diverged")
	}
	if got, _ := os.ReadFile(shadow + "-shm"); !bytesEqual(got, shmBody) {
		t.Fatal("shadow -shm sidecar diverged")
	}
	stShadow, _ := os.Stat(shadow)
	stReal, _ := os.Stat(real)
	if !stShadow.ModTime().Equal(stReal.ModTime()) {
		t.Errorf("copy2 parity: shadow mtime %v != real %v", stShadow.ModTime(), stReal.ModTime())
	}
	// …but writes land only in the shadow
	if err := os.WriteFile(shadow, []byte("dry-run-state"), 0o666); err != nil {
		t.Fatal(err)
	}
	if got, _ := os.ReadFile(real); !bytesEqual(got, realBody) {
		t.Fatal("a shadow write leaked into the real cache")
	}

	Disable()
	// after disable, the real cache is still untouched
	if got, _ := os.ReadFile(real); !bytesEqual(got, realBody) {
		t.Fatal("the real cache changed after disable")
	}
}

// Port of test_shadow_cache_missing_source_never_deadlocks — the
// fresh-install regression: shadow_cache_path must not hold the log lock
// while record() takes it. Run in a goroutine with a timeout so a
// regression FAILS instead of hanging the suite.
func TestShadowCacheMissingSourceNeverDeadlocks(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	missing := filepath.Join(t.TempDir(), "does-not-exist.db")
	Enable()
	box := make(chan string, 1)
	go func() { box <- ShadowCachePath(missing) }()
	var shadow string
	select {
	case shadow = <-box:
	case <-time.After(5 * time.Second):
		t.Fatal("shadow_cache_path deadlocked")
	}
	// the returned path is usable (a CacheDB-style open can create it)
	if err := os.WriteFile(shadow, []byte("x"), 0o600); err != nil {
		t.Fatalf("shadow path not usable: %v", err)
	}
	// the fresh-install case is recorded as info, not a crash
	sawInfo := false
	for _, e := range Entries() {
		if e.Op == "info" {
			sawInfo = true
		}
	}
	if !sawInfo {
		t.Error("missing source must be recorded as an info entry")
	}
}

// Port of test_report_markdown_renders_entries.
func TestReportMarkdownRendersEntries(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	Enable()
	Record("write", "/vault/Notes/note.md", "---\nsource: x\n---", "")
	Record("makedirs", "/vault/Notes", nil, "create folder")
	md := RenderReportMarkdown("Test report")
	for _, want := range []string{
		"Nothing below was written",
		"note.md",
		"makedirs",
		"2 operation(s)",
	} {
		if !strings.Contains(md, want) {
			t.Errorf("report missing %q", want)
		}
	}
}

