// Golden tests — the battery replayed against generated goldens
// (testdiff/goldens/dump_storage.py; rev-pinned 98f4fc7).
// ---------------------------------------------------------------------------

// battery mirrors the generator's BATTERY exactly (fixed path strings —
// record() never touches the disk); the golden arbitrates any drift.
var battery = []struct {
	op      string
	path    string
	content any
	note    string
}{
	{"write", "/vault/Notes/note.md", "# Title\r\n\nBody — émoji 🗑️ and | pipe\n", ""},
	{"append", "/vault/Notes/note.md", "more text", ""},
	{"write", "/vault/Notes/long.md", strings.Repeat("x", 300), ""},
	{"write", "/vault/Notes/cjk-str.md", strings.Repeat("数", 200), ""},
	{"write", "/vault/Notes/cjk-bytes.md", bytesRepeat("阿", 200), ""},
	{"banner", "/vault/banner.png", append([]byte("\x89PNG\r\n\x1a\n\xff\xfe"), bytesRepeat("y", 300)...), ""},
	{"makedirs", "/vault/Notes", nil, "create folder"},
	{"move", "/vault/Notes/new.md", nil, "from /vault/Notes/old.md"},
	{"remove", "/vault/Notes/old.md", nil, "delete file"},
	{"write", "/vault/Notes/empty.md", "", ""},
	{"append", "/vault/Notes/empty-bytes.db", []byte{}, ""},
	{"write", "/vault/Notes/just-under.md", strings.Repeat("y", 159), ""},
	{"write", "/vault/Notes/exact.md", strings.Repeat("z", 160), ""},
}

func bytesRepeat(s string, n int) []byte {
	return []byte(strings.Repeat(s, n))
}

func bytesEqual(a, b []byte) bool {
	return string(a) == string(b)
}

var tsRe = regexp.MustCompile(`^\d{2}:\d{2}:\d{2}$`)

func goldenText(t *testing.T, name string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_storage.py): %v", name, err)
	}
	return string(raw)
}

// normalize mirrors the generator's dump-time rules (doc 09 §3):
// HH:MM:SS → <TS> and the *Generated: ...* line → *Generated: <TS>*.
func normalizeReport(s string) string {
	ts := regexp.MustCompile(`\d{2}:\d{2}:\d{2}`)
	gen := regexp.MustCompile(`\*Generated: [^*]*\*`)
	return gen.ReplaceAllString(ts.ReplaceAllString(s, "<TS>"), "*Generated: <TS>*")
}

func TestGoldenDryrunEntries(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	var golden struct {
		Schema  int     `json:"schema"`
		Entries []Entry `json:"entries"`
		Summary [][]any `json:"summary_ordered"`
	}
	if err := json.Unmarshal([]byte(goldenText(t, "dryrun_entries.golden.json")), &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}

	Enable()
	for _, b := range battery {
		Record(b.op, b.path, b.content, b.note)
	}

	got := Entries()
	if len(got) != len(golden.Entries) {
		t.Fatalf("entry count = %d; golden has %d", len(got), len(golden.Entries))
	}
	for i := range got {
		if !tsRe.MatchString(got[i].Time) {
			t.Errorf("entry %d time %q does not match Python %%H:%%M:%%S", i, got[i].Time)
		}
		got[i].Time = "<TS>" // generator's dump-time normalization
	}
	if !reflect.DeepEqual(got, golden.Entries) {
		t.Fatalf("recorded entries drifted from the Python golden.\n--- want (python) --\n%+v\n--- got (go) --\n%+v",
			golden.Entries, got)
	}

	// summary() first-seen order is behavior (Python dict insertion order)
	sum := Summary()
	if len(sum) != len(golden.Summary) {
		t.Fatalf("summary len = %d; golden has %d", len(sum), len(golden.Summary))
	}
	for i, s := range sum {
		gOp, _ := golden.Summary[i][0].(string)
		gN, _ := golden.Summary[i][1].(float64)
		if s.Op != gOp || s.Count != int(gN) {
			t.Errorf("summary[%d] = {%s %d}; golden = {%s %v}", i, s.Op, s.Count, gOp, gN)
		}
	}
}

func TestGoldenDryrunReport(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	Enable()
	for _, b := range battery {
		Record(b.op, b.path, b.content, b.note)
	}
	got := normalizeReport(RenderReportMarkdown("Dry-run report"))
	if want := goldenText(t, "dryrun_report.golden.md"); got != want {
		t.Fatalf("report drifted from the Python golden.\n--- want (python) --\n%s\n--- got (go) --\n%s", want, got)
	}

	// the no-entries branch
	Clear()
	gotEmpty := normalizeReport(RenderReportMarkdown("Dry-run report"))
	if wantEmpty := goldenText(t, "dryrun_report_empty.golden.md"); gotEmpty != wantEmpty {
		t.Fatalf("empty report drifted.\n--- want --\n%s\n--- got --\n%s", wantEmpty, gotEmpty)
	}
}

// TestGoldenDryrunStandin replays the stand-in + shadow probes and compares
// the derived facts (op/note/size/preview; sha/mtime equalities; the two
// preserved quirks) against the generated golden.
func TestGoldenDryrunStandin(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	var golden struct {
		Schema             int             `json:"schema"`
		StandinOn          [][]any         `json:"standin_on"`
		ShadowReal         json.RawMessage `json:"shadow_real"`
		ShadowMissing      json.RawMessage `json:"shadow_missing"`
		ShadowDoubleEnable json.RawMessage `json:"shadow_double_enable"`
		ShadowCleanupQuirk json.RawMessage `json:"shadow_cleanup_quirk"`
	}
	if err := json.Unmarshal([]byte(goldenText(t, "dryrun_standin.golden.json")), &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}

	// --- stand-ins ON ---
	st := t.TempDir()
	if err := os.MkdirAll(filepath.Join(st, "exists"), 0o777); err != nil {
		t.Fatal(err)
	}
	Enable()
	Clear()
	_ = MkdirAll(filepath.Join(st, "exists"), true)     // 'folder exists'
	_ = MkdirAll(filepath.Join(st, "new-folder"), true) // 'create folder'
	_ = WriteText(filepath.Join(st, "w.txt"), "hello")
	_ = AppendText(filepath.Join(st, "w.txt"), "!")
	_ = Move(filepath.Join(st, "a.md"), filepath.Join(st, "b.md"))
	_ = Remove(filepath.Join(st, "a.md"))
	got := Entries()
	if len(got) != len(golden.StandinOn) {
		t.Fatalf("stand-in entries = %d; golden has %d", len(got), len(golden.StandinOn))
	}
	for i, e := range got {
		wantOp, _ := golden.StandinOn[i][0].(string)
		wantNote, _ := golden.StandinOn[i][1].(string)
		wantPreview, _ := golden.StandinOn[i][3].(string)
		wantSizeNil := golden.StandinOn[i][2] == nil
		note := strings.ReplaceAll(e.Note, st, "<TMP>") // generator's temp-path rule
		if e.Op != wantOp || note != wantNote || e.Preview != wantPreview {
			t.Errorf("stand-in[%d] = {%s %q %q}; golden = {%s %q %q}",
				i, e.Op, note, e.Preview, wantOp, wantNote, wantPreview)
		}
		if wantSizeNil != (e.Size == nil) {
			t.Errorf("stand-in[%d] size nil-ness = %v; golden nil = %v", i, e.Size == nil, wantSizeNil)
		}
		if e.Size != nil {
			wantSize, _ := golden.StandinOn[i][2].(float64)
			if *e.Size != int(wantSize) {
				t.Errorf("stand-in[%d] size = %d; golden = %v", i, *e.Size, wantSize)
			}
		}
	}
	Disable()
	Clear()

	// --- shadow: real source with WAL sidecars ---
	sh := t.TempDir()
	realDB := filepath.Join(sh, "cache.db")
	realBody := []byte("REAL-CACHE-" + strings.Repeat("0123456789abcdef", 64))
	walBody := []byte("WAL-" + strings.Repeat("\x00\x01\x02", 33))
	shmBody := []byte("SHM-" + strings.Repeat("\xff", 100))
	for p, b := range map[string][]byte{realDB: realBody, realDB + "-wal": walBody, realDB + "-shm": shmBody} {
		if err := os.WriteFile(p, b, 0o666); err != nil {
			t.Fatal(err)
		}
	}
	Enable()
	sh1 := ShadowCachePath(realDB)
	var wantReal struct {
		Basename       string   `json:"basename"`
		DirPrefixOK    bool     `json:"dir_prefix_ok"`
		ShadowShaEq    bool     `json:"shadow_sha_eq"`
		WalShaEq       bool     `json:"wal_sha_eq"`
		ShmShaEq       bool     `json:"shm_sha_eq"`
		MtimeEqual     bool     `json:"mtime_equal"`
		RecordedOps    []string `json:"recorded_ops"`
		SecondCallSame bool     `json:"second_call_same"`
	}
	if err := json.Unmarshal(golden.ShadowReal, &wantReal); err != nil {
		t.Fatalf("parse golden shadow_real: %v", err)
	}
	if filepath.Base(sh1) != wantReal.Basename {
		t.Errorf("shadow basename = %q; golden %q", filepath.Base(sh1), wantReal.Basename)
	}
	if dirPrefix := filepath.Base(filepath.Dir(sh1)); strings.HasPrefix(dirPrefix, "gitcurator-dryrun-") != wantReal.DirPrefixOK {
		t.Errorf("shadow dir prefix gitcurator-dryrun-: got %q", dirPrefix)
	}
	checkEq := func(name string, gotEq bool, wantEq bool) {
		if gotEq != wantEq {
			t.Errorf("%s: got %v; golden %v", name, gotEq, wantEq)
		}
	}
	shadowBytes, _ := os.ReadFile(sh1)
	checkEq("shadow bytes", bytesEqual(shadowBytes, realBody), wantReal.ShadowShaEq)
	walBytes, _ := os.ReadFile(sh1 + "-wal")
	checkEq("wal bytes", bytesEqual(walBytes, walBody), wantReal.WalShaEq)
	shmBytes, _ := os.ReadFile(sh1 + "-shm")
	checkEq("shm bytes", bytesEqual(shmBytes, shmBody), wantReal.ShmShaEq)
	stS, _ := os.Stat(sh1)
	stR, _ := os.Stat(realDB)
	checkEq("mtime", stS.ModTime().Equal(stR.ModTime()), wantReal.MtimeEqual)
	var recordedOps []string
	for _, e := range Entries() {
		recordedOps = append(recordedOps, e.Op)
	}
	if recordedOps == nil {
		recordedOps = []string{} // match the golden's empty-array shape
	}
	if wantReal.RecordedOps == nil {
		wantReal.RecordedOps = []string{}
	}
	if !reflect.DeepEqual(recordedOps, wantReal.RecordedOps) {
		t.Errorf("recorded ops after a successful copy = %v; golden %v", recordedOps, wantReal.RecordedOps)
	}
	checkEq("second call cached", ShadowCachePath(realDB) == sh1, wantReal.SecondCallSame)

	// --- missing source → info entry ---
	Disable()
	Clear()
	Enable()
	missing := filepath.Join(sh, "does-not-exist.db")
	sh2 := ShadowCachePath(missing)
	var wantMissing struct {
		Basename  string `json:"basename"`
		InfoNote  string `json:"info_note"`
		InfoCount int    `json:"info_count"`
	}
	if err := json.Unmarshal(golden.ShadowMissing, &wantMissing); err != nil {
		t.Fatalf("parse golden shadow_missing: %v", err)
	}
	infoCount := 0
	var infoNote string
	for _, e := range Entries() {
		if e.Op == "info" {
			infoCount++
			infoNote = e.Note
		}
	}
	if filepath.Base(sh2) != wantMissing.Basename {
		t.Errorf("missing-source shadow basename = %q; golden %q", filepath.Base(sh2), wantMissing.Basename)
	}
	if infoCount != wantMissing.InfoCount || infoNote != wantMissing.InfoNote {
		t.Errorf("info entry = {count %d, note %q}; golden {count %d, note %q}",
			infoCount, infoNote, wantMissing.InfoCount, wantMissing.InfoNote)
	}

	// --- preserved quirk 1: enable() does NOT reset the shadow dir — a
	// second enable reuses the SAME temp dir (dryrun.py 74-80; documented
	// in SESSION-004, preserved literally per doc 09 §5). ---
	sh2Dir := filepath.Dir(sh2)
	Enable()
	sh3 := ShadowCachePath(missing)
	var wantDouble struct {
		SameDir  bool `json:"same_dir"`
		SamePath bool `json:"same_path"`
	}
	if err := json.Unmarshal(golden.ShadowDoubleEnable, &wantDouble); err != nil {
		t.Fatalf("parse golden shadow_double_enable: %v", err)
	}
	checkEq("double-enable same dir", filepath.Dir(sh3) == sh2Dir, wantDouble.SameDir)
	checkEq("double-enable same path", sh3 == sh2, wantDouble.SamePath)

	// --- preserved quirk 2: disable()'s shadow cleanup is dead code
	// (dryrun.py 83-90 zeroes _shadow_dir BEFORE _cleanup_shadow_dir reads
	// it) — the temp dir SURVIVES disable. ---
	Disable()
	var wantQuirk struct {
		DirSurvivesDisable bool `json:"dir_survives_disable"`
	}
	if err := json.Unmarshal(golden.ShadowCleanupQuirk, &wantQuirk); err != nil {
		t.Fatalf("parse golden shadow_cleanup_quirk: %v", err)
	}
	_, statErr := os.Stat(sh2Dir)
	survives := os.IsNotExist(statErr) == false
	checkEq("shadow dir survives disable (dead cleanup)", survives, wantQuirk.DirSurvivesDisable)
}

// TestRecordNeverPanics pins record()'s "never raises" contract: unknown
// content types and odd inputs must be swallowed, not crash the batch.
func TestRecordNeverPanics(t *testing.T) {
	setUp(t)
	defer tearDown(t)

	Enable()
	Record("write", "/x.md", 42, "") // non-str/bytes content: size None
	Record("write", "/x.md", []string{"a"}, "")
	Record("", "", nil, "")
	Record("op", "p", "c", "note")
	if got := EntryCount(); got != 4 {
		t.Fatalf("entry_count = %d; want 4 (record never drops entries for odd content)", got)
	}
	for _, e := range Entries()[:2] {
		if e.Size != nil {
			t.Errorf("odd-content entry size = %v; want nil", *e.Size)
		}
	}
}
